FUNCTION_BLOCK FB_PlasmaTest_ArcHeaterPressure
(* ========================================================================================= *)
(* LUMINA HYPERSONICS AEROTHERMAL SIMULATION & GROUND TEST FACILITY CONTROL ARCHITECTURE    *)
(* CYBER-PHYSICAL SYSTEMS ENGINEERING & AUTOMATION CO-DESIGN - IEC 61131-3 COMPLIANT       *)
(*                                                                                           *)
(* FUNCTION BLOCK: FB_PlasmaTest_ArcHeaterPressure                                          *)
(* DESCRIPTION   : High-Enthalpy Constricted-Arc Plasma Generator Multi-Variable Controller *)
(*                 Manages Sonic Throat Stagnation Pressure (P0) and Bulk Enthalpy (H0)     *)
(*                 via Model Predictive Control (MPC), Discrete State-Space Observer,        *)
(*                 Caloric Enthalpy Balance, 2oo3 TMR Transducer Voting, and Critical Heat    *)
(*                 Flux (CHF) Subcooled Nucleate Boiling Protection for Segmented Electrodes *)
(* ========================================================================================= *)

VAR_INPUT
    (* Master Execution and Safety Permissives *)
    bEnable                 : BOOL;     (* Facility System Master Run Enable [BOOL] *)
    bEmergencyStop          : BOOL;     (* Hardwired Safety Relay Circuit OK - Fail-Safe High [BOOL] *)
    bArcIgnitionCmd         : BOOL;     (* High-Voltage Spark / Exploding Wire Pulse Fire Trigger [BOOL] *)

    (* Primary Plasma Arc Electrical Transducers *)
    rArcCurrent_kA          : REAL;     (* Main DC Arc Current Feedback from Hall-Effect Shunt [kA] *)
    rArcVoltage_V           : REAL;     (* Main DC Arc Terminal Voltage Feedback Transducer [V] *)
    rTargetPower_MW         : REAL;     (* Maximum Allowable Electrical Power Allocation [MW] *)

    (* 2oo3 Triple Modular Redundancy (TMR) Plenum Stagnation Pressure Instrumentation *)
    rPressPlenum_ChA_bar    : REAL;     (* Chamber Stagnation Pressure Ch-A Piezo-Resistive [bar] *)
    rPressPlenum_ChB_bar    : REAL;     (* Chamber Stagnation Pressure Ch-B Piezo-Resistive [bar] *)
    rPressPlenum_ChC_bar    : REAL;     (* Chamber Stagnation Pressure Ch-C Optical Diaphragm [bar] *)

    (* Gas Dynamic and Aerothermal Injection Feeds *)
    rGasMassFlow_gps        : REAL;     (* Primary High-Pressure Gas Injected Mass Flow Rate [g/s] *)
    rTargetStagPress_bar    : REAL;     (* Target Hypersonic Plenum Stagnation Pressure Setpoint [bar] *)
    rTargetEnthalpy_MJpkg   : REAL;     (* Target Bulk Plasma Stagnation Specific Enthalpy [MJ/kg] *)
    rNozzleThroatDiam_mm    : REAL;     (* Supersonic Convergent-Divergent Throat Diameter [mm] *)

    (* Deionized Electrode Cooling Subsystem Transducers *)
    rCoolWaterFlow_Lps      : REAL;     (* Deionized Coolant Volumetric Flow to Arc Ring Electrodes [L/s] *)
    rCoolWaterTin_degC      : REAL;     (* Deionized Coolant Inflow Supply Manifold Temperature [deg C] *)
    rCoolWaterTout_degC     : REAL;     (* Deionized Coolant Discharge Return Manifold Temperature [deg C] *)
    rCoolWaterPin_bar       : REAL;     (* Coolant High-Pressure Supply Delivery Pressure [bar] *)
    rCoolWaterPout_bar      : REAL;     (* Coolant Discharge Recovery Line Pressure [bar] *)

    (* Execution Timing *)
    tSamplePeriod           : TIME := T#10MS; (* Synchronous Deterministic Task Sample Period *)
END_VAR

VAR_OUTPUT
    (* Facility Ready and Safety Interlock Interfacing *)
    bSystemReady            : BOOL;     (* Facility Subsystems Primed and Arc-Run Permissive Set [BOOL] *)
    bArcPowerPermissive     : BOOL;     (* Interlock Permissive for High-Voltage SCR Rectifier [BOOL] *)
    bEmergencyCrowbarFire   : BOOL;     (* Ultra-Fast Ignitron/Thyristor Arc Dump Crowbar Fire [BOOL] *)

    (* Real-Time Closed-Loop Control Demands *)
    rGasControlValve_pct    : REAL;     (* Electro-Pneumatic Gas Throttle Valve Command [0.0 - 100.0 %] *)
    rArcCurrentDemand_kA    : REAL;     (* Phase-Angle SCR Rectifier Arc Current Setpoint [kA] *)

    (* Validated Process Instrumentation and Caloric States *)
    rVotedPlenumPress_bar   : REAL;     (* 2oo3 Triple Modular Redundancy Validated Chamber Pressure [bar] *)
    rEstBulkEnthalpy_MJpkg  : REAL;     (* Real-Time Sonic Choked / Caloric Plasma Enthalpy [MJ/kg] *)
    rElectrodeHeatFlux_MW   : REAL;     (* Calorimetric Heat Dissipation into Electrode Cooling Jacket [MW] *)
    rCHF_MarginRatio        : REAL;     (* Critical Heat Flux Margin to Film Boiling Departure [-] *)

    (* Operational Diagnostics and Alarm Words *)
    wSensorHealthWord       : WORD;     (* Transducer Integrity and 2oo3 TMR Fault Status Vector *)
    wSystemStatusWord       : WORD;     (* Finite State Machine Subsystem and Permissive Bitmask *)
    bCriticalFaultAlarm     : BOOL;     (* Process Shutdown Latched Alarm Trigger [BOOL] *)
END_VAR

VAR
    (* Finite State Machine State Registers *)
    iState                  : INT := 0;  (* 0=Offline, 10=Purge, 20=Ignite, 30=Ramp, 40=Run, 50=PostCool, 90=Abort *)
    iSubState               : INT := 0;

    (* First-Order Exponential Moving Average (EMA) Digital Filters *)
    rArcVoltage_Filt        : REAL := 0.0;
    rArcCurrent_Filt        : REAL := 0.0;
    rGasMassFlow_Filt       : REAL := 0.0;
    rPressChA_Filt          : REAL := 0.0;
    rPressChB_Filt          : REAL := 0.0;
    rPressChC_Filt          : REAL := 0.0;
    rAlpha_ElecFilter       : REAL := 0.18; (* EMA coefficient for electrical hash attenuation *)
    rAlpha_PressFilter      : REAL := 0.25; (* EMA coefficient for pressure acoustic damping *)

    (* 2oo3 Triple Modular Redundancy (TMR) Voting Architecture *)
    bChA_Healthy            : BOOL := TRUE;
    bChB_Healthy            : BOOL := TRUE;
    bChC_Healthy            : BOOL := TRUE;
    rDev_AB                 : REAL := 0.0;
    rDev_BC                 : REAL := 0.0;
    rDev_CA                 : REAL := 0.0;
    rPressTolerance_bar     : REAL := 1.25; (* Max channel divergence threshold before isolation [bar] *)
    iTMR_DegradedMode       : INT := 0;     (* 0=Nominal 2oo3, 1=Degraded 1oo2, 2=Hardware Fail-Safe *)
    iFaultCounter_A         : INT := 0;
    iFaultCounter_B         : INT := 0;
    iFaultCounter_C         : INT := 0;

    (* Model Predictive Control (MPC) and Linear State-Space Observer Matrices *)
    (* State Vector x = [ Delta_P0 (bar), Delta_H0 (MJ/kg) ]^T                             *)
    (* Control Vector u = [ Delta_Valve (%), Delta_Current (kA) ]^T                        *)
    (* Linearized Plant Discretization at Ts = 10 ms                                       *)
    aA_mat                  : ARRAY[1..2, 1..2] OF REAL := [0.965, 0.008, -0.012, 0.940];
    aB_mat                  : ARRAY[1..2, 1..2] OF REAL := [0.045, 0.015, -0.035, 0.082];
    aC_mat                  : ARRAY[1..2, 1..2] OF REAL := [1.000, 0.000, 0.000, 1.000];
    aL_gain                 : ARRAY[1..2, 1..2] OF REAL := [0.245, 0.004, -0.006, 0.198];
    aK_mpc                  : ARRAY[1..2, 1..2] OF REAL := [1.820, -0.175, -0.285, 1.340];
    aKr_ff                  : ARRAY[1..2, 1..2] OF REAL := [1.850, 0.000, 0.000, 1.480];

    (* Observer and Controller State Vectors *)
    ax_est                  : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Filtered Kalman/Luenberger State Estimate *)
    ax_pred                 : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* One-Step Ahead Internal Model Prediction *)
    au_ctl                  : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Computed Raw Feedback Injections *)
    ay_innov                : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Innovation Measurement Error Vector *)

    (* Thermodynamic and Caloric Energy Balance Variables *)
    rElecPower_MW           : REAL := 0.0; (* Arc Electrical Energy: V_arc * I_arc [MW] *)
    rCaloricHeat_MW         : REAL := 0.0; (* Heat flux into DI water: m_dot * Cp * deltaT [MW] *)
    rNetPlasmaPower_MW      : REAL := 0.0; (* Net Useful Thermal Power Delivered to Plasma Stream [MW] *)
    rPlasmaThermalEfficiency: REAL := 0.0; (* (P_elec - Q_caloric) / P_elec ratio *)
    rCoolantDeltaP_bar      : REAL := 0.0; (* Cooling differential pressure Pin - Pout [bar] *)
    rCoolantDeltaT_degC     : REAL := 0.0; (* Coolant temperature rise Tout - Tin [deg C] *)
    rCoolantDensity_kgpL    : REAL := 0.997;(* Specific mass density of deionized water [kg/L] *)
    rCoolantCp_kJpkgK       : REAL := 4.184;(* Specific isobaric heat capacity of DI water [kJ/kg-K] *)
    rElectrodeSurfaceArea_m2: REAL := 0.145;(* Effective heat absorption area of copper electrode ring [m2] *)
    rLocalHeatFlux_MWpm2    : REAL := 0.0; (* Peak localized thermal heat flux [MW/m2] *)
    rSatTempCoolant_degC    : REAL := 100.0;(* Saturated liquid temperature at local return pressure *)
    rSubcoolingDeltaT_degC  : REAL := 0.0; (* Subcooled fluid margin: T_sat - T_out [deg C] *)
    rCoolantVelocity_mps    : REAL := 0.0; (* Bulk hydraulic speed in annular electrode channels [m/s] *)
    rCHF_Critical_MWpm2     : REAL := 0.0; (* Bergles-Rohsenow subcooled burnout heat flux threshold *)

    (* Aerothermal Gas Dynamics Constants *)
    rGasConstant_R          : REAL := 287.05; (* Universal Specific Gas Constant for Dry Air [J/kg-K] *)
    rGamma                  : REAL := 1.40;   (* Specific Heat Ratio for Molecular Nitrogen/Air *)
    rSonicChokedConstant    : REAL := 0.0404; (* Choked throat mass-flow characteristic parameter *)
    rNozzleThroatArea_m2    : REAL := 0.0;    (* Geometric area of choked expansion throat [m2] *)

    (* Rate Limiters, Setpoint Ramp Accumulators, and Base Offsets *)
    rNominalPressureBase_bar: REAL := 25.0;  (* Linearization equilibrium pressure operating point [bar] *)
    rNominalEnthalpyBase_MJ : REAL := 12.0;  (* Linearization equilibrium enthalpy operating point [MJ/kg] *)
    rNominalValveBase_pct   : REAL := 48.0;  (* Steady-state gas valve bias at nominal equilibrium [%] *)
    rNominalCurrentBase_kA  : REAL := 3.20;  (* Steady-state arc current bias at nominal equilibrium [kA] *)
    rActivePressSetpoint_bar: REAL := 0.0;
    rActiveEnthalpy_MJpkg   : REAL := 0.0;
    rRampRatePress_barps    : REAL := 2.50;  (* Maximum soft ramp rate for chamber pressurization [bar/s] *)
    rRampRateCurrent_kAps   : REAL := 0.80;  (* Maximum soft ramp rate for DC arc power [kA/s] *)

    (* Industrial Safety & Sequencing Timers *)
    tonPurgeTimer           : TON; (* Pre-test chamber and line gas purge verification *)
    tonIgnitionArcWindow    : TON; (* Maximum permissive window for arc breakdown detection *)
    tonRampStabilizer       : TON; (* Settle timer between ramp stages *)
    tonCooldownTimer        : TON; (* Post-test electrode cooling circulation timer *)
    tonCrowbarHold          : TON; (* Fast Crowbar discharge pulse duration *)

    (* Scratch and Index Registers *)
    i                       : INT;
    j                       : INT;
    rTempMin                : REAL;
    rTempMax                : REAL;
    rTempSum                : REAL;
    rCycleTime_s            : REAL := 0.010; (* Fixed 10 ms cycle in seconds *)
END_VAR

(* ========================================================================================= *)
(* 1. HARDWIRED SAFETY CIRCUIT AND FAST INTERLOCK SUPERVISION                                *)
(* ========================================================================================= *)
IF NOT bEmergencyStop THEN
    bEmergencyCrowbarFire   := TRUE;
    bArcPowerPermissive     := FALSE;
    bSystemReady            := FALSE;
    bCriticalFaultAlarm     := TRUE;
    rGasControlValve_pct    := 0.0;
    rArcCurrentDemand_kA    := 0.0;
    iState                  := 90; (* Jump directly to Emergency Abort state *)
    wSystemStatusWord       := 16#0080;
    RETURN;
END_IF;

(* ========================================================================================= *)
(* 2. SENSOR SIGNAL CONDITIONING AND DIGITAL FILTERING (EMA)                                *)
(* ========================================================================================= *)
(* Attenuate high-frequency plasma turbulence and phase-controlled rectifier commutation spikes *)
rArcVoltage_Filt    := (rAlpha_ElecFilter * rArcVoltage_V) + ((1.0 - rAlpha_ElecFilter) * rArcVoltage_Filt);
rArcCurrent_Filt    := (rAlpha_ElecFilter * rArcCurrent_kA) + ((1.0 - rAlpha_ElecFilter) * rArcCurrent_Filt);
rGasMassFlow_Filt   := (rAlpha_PressFilter * rGasMassFlow_gps) + ((1.0 - rAlpha_PressFilter) * rGasMassFlow_Filt);
rPressChA_Filt      := (rAlpha_PressFilter * rPressPlenum_ChA_bar) + ((1.0 - rAlpha_PressFilter) * rPressChA_Filt);
rPressChB_Filt      := (rAlpha_PressFilter * rPressPlenum_ChB_bar) + ((1.0 - rAlpha_PressFilter) * rPressChB_Filt);
rPressChC_Filt      := (rAlpha_PressFilter * rPressPlenum_ChC_bar) + ((1.0 - rAlpha_PressFilter) * rPressChC_Filt);

(* ========================================================================================= *)
(* 3. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) STAGNATION PRESSURE VOTING                       *)
(* ========================================================================================= *)
(* Cross-channel deviation calculation *)
rDev_AB := ABS(rPressChA_Filt - rPressChB_Filt);
rDev_BC := ABS(rPressChB_Filt - rPressChC_Filt);
rDev_CA := ABS(rPressChC_Filt - rPressChA_Filt);

(* Sensor anomaly confirmation persistence counter *)
IF (rDev_AB > rPressTolerance_bar) AND (rDev_CA > rPressTolerance_bar) THEN
    iFaultCounter_A := iFaultCounter_A + 1;
    IF iFaultCounter_A > 15 THEN (* 150 ms persistence *)
        bChA_Healthy := FALSE;
    END_IF;
ELSE
    IF iFaultCounter_A > 0 THEN iFaultCounter_A := iFaultCounter_A - 1; END_IF;
END_IF;

IF (rDev_AB > rPressTolerance_bar) AND (rDev_BC > rPressTolerance_bar) THEN
    iFaultCounter_B := iFaultCounter_B + 1;
    IF iFaultCounter_B > 15 THEN
        bChB_Healthy := FALSE;
    END_IF;
ELSE
    IF iFaultCounter_B > 0 THEN iFaultCounter_B := iFaultCounter_B - 1; END_IF;
END_IF;

IF (rDev_BC > rPressTolerance_bar) AND (rDev_CA > rPressTolerance_bar) THEN
    iFaultCounter_C := iFaultCounter_C + 1;
    IF iFaultCounter_C > 15 THEN
        bChC_Healthy := FALSE;
    END_IF;
ELSE
    IF iFaultCounter_C > 0 THEN iFaultCounter_C := iFaultCounter_C - 1; END_IF;
END_IF;

(* 2oo3 Median Voting Algorithm with Graceful Degradation *)
IF bChA_Healthy AND bChB_Healthy AND bChC_Healthy THEN
    (* All 3 channels healthy: True median selection *)
    iTMR_DegradedMode := 0;
    rTempSum := rPressChA_Filt + rPressChB_Filt + rPressChC_Filt;
    rTempMin := MIN(rPressChA_Filt, MIN(rPressChB_Filt, rPressChC_Filt));
    rTempMax := MAX(rPressChA_Filt, MAX(rPressChB_Filt, rPressChC_Filt));
    rVotedPlenumPress_bar := rTempSum - rTempMin - rTempMax;
ELSIF bChA_Healthy AND bChB_Healthy THEN
    (* Ch-C isolated: Degraded to 1oo2 average *)
    iTMR_DegradedMode := 1;
    rVotedPlenumPress_bar := (rPressChA_Filt + rPressChB_Filt) * 0.5;
ELSIF bChB_Healthy AND bChC_Healthy THEN
    (* Ch-A isolated: Degraded to 1oo2 average *)
    iTMR_DegradedMode := 1;
    rVotedPlenumPress_bar := (rPressChB_Filt + rPressChC_Filt) * 0.5;
ELSIF bChA_Healthy AND bChC_Healthy THEN
    (* Ch-B isolated: Degraded to 1oo2 average *)
    iTMR_DegradedMode := 1;
    rVotedPlenumPress_bar := (rPressChA_Filt + rPressChC_Filt) * 0.5;
ELSE
    (* Multiple transducer failures: Fail-safe mode *)
    iTMR_DegradedMode   := 2;
    bCriticalFaultAlarm := TRUE;
    wSensorHealthWord   := 16#0010; (* TMR catastrophic failure bit *)
    iState              := 90;      (* Abort immediately *)
END_IF;

(* ========================================================================================= *)
(* 4. ELECTRODE COOLING CALORIMETRIC BALANCE & CRITICAL HEAT FLUX (CHF) SAFETY                *)
(* ========================================================================================= *)
(* Hydraulic pressure drop across electrode cooling jacket *)
rCoolantDeltaP_bar := rCoolWaterPin_bar - rCoolWaterPout_bar;

(* Calorimetric thermal dissipation computation: Q = m_dot * Cp * deltaT *)
rCoolantDeltaT_degC := rCoolWaterTout_degC - rCoolWaterTin_degC;
IF rCoolantDeltaT_degC < 0.0 THEN
    rCoolantDeltaT_degC := 0.0;
END_IF;

(* Mass flow rate in kg/s = Flow (L/s) * Density (kg/L) *)
rCaloricHeat_MW := (rCoolWaterFlow_Lps * rCoolantDensity_kgpL) * (rCoolantCp_kJpkgK * 0.001) * rCoolantDeltaT_degC;
rElectrodeHeatFlux_MW := rCaloricHeat_MW;

(* Arc Electrical Input Power in MW *)
rElecPower_MW := (rArcVoltage_Filt * rArcCurrent_Filt) * 0.001;

(* Local peak heat flux on copper constrictor wall (MW/m2) *)
rLocalHeatFlux_MWpm2 := (rCaloricHeat_MW * 1.65) / rElectrodeSurfaceArea_m2;

(* Saturation temperature estimation at local backpressure *)
IF rCoolWaterPout_bar > 1.0 THEN
    rSatTempCoolant_degC := 100.0 + (28.4 * LN(rCoolWaterPout_bar));
ELSE
    rSatTempCoolant_degC := 100.0;
END_IF;

(* Fluid subcooling margin *)
rSubcoolingDeltaT_degC := rSatTempCoolant_degC - rCoolWaterTout_degC;
IF rSubcoolingDeltaT_degC < 0.0 THEN
    rSubcoolingDeltaT_degC := 0.0;
END_IF;

(* Annular channel coolant velocity (m/s) approx based on 25 mm equivalent hydraulic bore *)
rCoolantVelocity_mps := rCoolWaterFlow_Lps * 0.85;

(* Modified Bergles-Rohsenow Critical Heat Flux correlation for high-velocity subcooled DI water *)
rCHF_Critical_MWpm2 := 12.5 + (0.35 * rSubcoolingDeltaT_degC) + (1.45 * rCoolantVelocity_mps);

(* Critical Heat Flux Margin Ratio *)
IF rLocalHeatFlux_MWpm2 > 0.05 THEN
    rCHF_MarginRatio := rCHF_Critical_MWpm2 / rLocalHeatFlux_MWpm2;
ELSE
    rCHF_MarginRatio := 10.0; (* Cold electrode, boundless margin *)
END_IF;

(* Real-Time Caloric Bulk Gas Enthalpy Balance *)
IF rGasMassFlow_Filt > 0.5 THEN
    (* Gas mass flow in kg/s = g/s / 1000.0 *)
    (* Bulk Enthalpy H0 [MJ/kg] = (P_elec [MW] - Q_cooling [MW]) / m_dot [kg/s] *)
    rNetPlasmaPower_MW := rElecPower_MW - rCaloricHeat_MW;
    IF rNetPlasmaPower_MW < 0.0 THEN rNetPlasmaPower_MW := 0.0; END_IF;
    rEstBulkEnthalpy_MJpkg := rNetPlasmaPower_MW / (rGasMassFlow_Filt * 0.001);
ELSE
    rEstBulkEnthalpy_MJpkg := 0.0;
END_IF;

(* Cooling safety interlock validation *)
IF (rCoolWaterFlow_Lps < 14.5) OR (rCoolantDeltaP_bar < 3.5) OR (rCoolWaterTout_degC > 82.0) THEN
    wSensorHealthWord := 16#0020; (* Cooling water hazard bit *)
    IF (iState >= 20) AND (iState < 50) THEN
        (* Active arc present with cooling degradation: Fast Emergency Dump *)
        bEmergencyCrowbarFire   := TRUE;
        bArcPowerPermissive     := FALSE;
        bCriticalFaultAlarm     := TRUE;
        iState                  := 90;
    END_IF;
END_IF;

IF rCHF_MarginRatio < 1.35 THEN
    wSensorHealthWord := 16#0100; (* Critical Heat Flux Warning *)
    IF rCHF_MarginRatio < 1.12 THEN
        (* Imminent subcooled boiling departure / electrode wall burnout *)
        bEmergencyCrowbarFire   := TRUE;
        bArcPowerPermissive     := FALSE;
        bCriticalFaultAlarm     := TRUE;
        iState                  := 90;
    END_IF;
END_IF;

(* ========================================================================================= *)
(* 5. DISCRETE STATE-SPACE OBSERVER & MODEL PREDICTIVE CONTROL (MPC)                        *)
(* ========================================================================================= *)
(* State innovation update: y_innov = y_meas - C * x_pred *)
ay_innov[1] := (rVotedPlenumPress_bar - rNominalPressureBase_bar) - (aC_mat[1,1] * ax_pred[1] + aC_mat[1,2] * ax_pred[2]);
ay_innov[2] := (rEstBulkEnthalpy_MJpkg - rNominalEnthalpyBase_MJ) - (aC_mat[2,1] * ax_pred[1] + aC_mat[2,2] * ax_pred[2]);

(* State correction: x_est = x_pred + L * y_innov *)
ax_est[1] := ax_pred[1] + (aL_gain[1,1] * ay_innov[1] + aL_gain[1,2] * ay_innov[2]);
ax_est[2] := ax_pred[2] + (aL_gain[2,1] * ay_innov[1] + aL_gain[2,2] * ay_innov[2]);

(* Model Predictive Control feedback computation: u_ctl = -K * x_est + Kr * r_ref *)
au_ctl[1] := - (aK_mpc[1,1] * ax_est[1] + aK_mpc[1,2] * ax_est[2]) 
             + (aKr_ff[1,1] * (rActivePressSetpoint_bar - rNominalPressureBase_bar));

au_ctl[2] := - (aK_mpc[2,1] * ax_est[1] + aK_mpc[2,2] * ax_est[2]) 
             + (aKr_ff[2,2] * (rActiveEnthalpy_MJpkg - rNominalEnthalpyBase_MJ));

(* One-step ahead model state prediction: x_pred = A * x_est + B * u_ctl *)
ax_pred[1] := (aA_mat[1,1] * ax_est[1] + aA_mat[1,2] * ax_est[2]) + (aB_mat[1,1] * au_ctl[1] + aB_mat[1,2] * au_ctl[2]);
ax_pred[2] := (aA_mat[2,1] * ax_est[1] + aA_mat[2,2] * ax_est[2]) + (aB_mat[2,1] * au_ctl[1] + aB_mat[2,2] * au_ctl[2]);

(* ========================================================================================= *)
(* 6. MULTI-STAGE FINITE STATE MACHINE (CASE iState OF)                                     *)
(* ========================================================================================= *)
CASE iState OF

    0: (* STATE 0: INHIBIT_OFFLINE *)
        bSystemReady            := FALSE;
        bArcPowerPermissive     := FALSE;
        bEmergencyCrowbarFire   := FALSE;
        rGasControlValve_pct    := 0.0;
        rArcCurrentDemand_kA    := 0.0;
        rActivePressSetpoint_bar:= 0.0;
        rActiveEnthalpy_MJpkg   := 0.0;
        bCriticalFaultAlarm     := FALSE;
        wSystemStatusWord       := 16#0001; (* State 0 Bit *)

        (* Transition to Standby Purge when Master Enable and Safety Relays OK *)
        IF bEnable AND bEmergencyStop THEN
            IF (rCoolWaterFlow_Lps >= 15.0) AND (rCoolantDeltaP_bar >= 4.0) THEN
                iState := 10;
            END_IF;
        END_IF;

    10: (* STATE 10: PRETEST_PURGE_COOLING_VERIFICATION *)
        wSystemStatusWord       := 16#0002; (* State 10 Bit *)
        bArcPowerPermissive     := FALSE;
        bEmergencyCrowbarFire   := FALSE;

        (* Open gas throttle valve to purge air and establish baseline chamber flow *)
        rGasControlValve_pct    := 18.0;
        rArcCurrentDemand_kA    := 0.0;

        (* Require 3.5 seconds of sustained flow and pressure stability *)
        tonPurgeTimer(IN := (rGasMassFlow_gps > 40.0) AND (rCoolWaterFlow_Lps > 15.0), PT := T#3500MS);
        IF tonPurgeTimer.Q THEN
            tonPurgeTimer(IN := FALSE);
            bSystemReady := TRUE;
            IF bArcIgnitionCmd THEN
                iState := 20; (* Proceed to Ignition Sequence *)
            END_IF;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE 20: IGNITION_BREAKDOWN_SEQUENCE *)
        wSystemStatusWord       := 16#0004; (* State 20 Bit *)
        bSystemReady            := TRUE;
        bArcPowerPermissive     := TRUE;

        (* Provide starting pilot current demand and optimal ignition gas density *)
        rGasControlValve_pct    := 22.0;
        rArcCurrentDemand_kA    := 1.20; (* Pilot arc baseline current [kA] *)

        (* Supervise arc breakdown: current must cross threshold within 600 ms *)
        tonIgnitionArcWindow(IN := TRUE, PT := T#600MS);

        IF (rArcCurrent_Filt > 0.85) AND (rArcVoltage_Filt > 250.0) THEN
            (* Successful dielectric breakdown and sustained plasma column *)
            tonIgnitionArcWindow(IN := FALSE);
            rActivePressSetpoint_bar := rVotedPlenumPress_bar;
            rActiveEnthalpy_MJpkg    := 8.0;
            iState := 30; (* Proceed to Ramp *)
        ELSIF tonIgnitionArcWindow.Q THEN
            (* Ignition failure: arc failed to establish *)
            tonIgnitionArcWindow(IN := FALSE);
            bArcPowerPermissive := FALSE;
            bCriticalFaultAlarm := TRUE;
            wSensorHealthWord   := 16#0200; (* Ignition failure alarm *)
            iState := 90;
        END_IF;

    30: (* STATE 30: ARC_CURRENT_AND_PRESSURE_RAMP *)
        wSystemStatusWord   := 16#0008; (* State 30 Bit *)
        bArcPowerPermissive := TRUE;

        (* Coordinated soft rate ramp toward aerothermal setpoints *)
        IF rActivePressSetpoint_bar < rTargetStagPress_bar THEN
            rActivePressSetpoint_bar := rActivePressSetpoint_bar + (rRampRatePress_barps * rCycleTime_s);
            IF rActivePressSetpoint_bar > rTargetStagPress_bar THEN
                rActivePressSetpoint_bar := rTargetStagPress_bar;
            END_IF;
        END_IF;

        IF rActiveEnthalpy_MJpkg < rTargetEnthalpy_MJpkg THEN
