        IF rGasControlValve_pct > 92.0 THEN rGasControlValve_pct := 92.0; END_IF;
        IF rGasControlValve_pct < 12.0 THEN rGasControlValve_pct := 12.0; END_IF;
        IF rArcCurrentDemand_kA > 7.50 THEN rArcCurrentDemand_kA := 7.50; END_IF;
        IF rArcCurrentDemand_kA < 1.00 THEN rArcCurrentDemand_kA := 1.00; END_IF;

        (* Check ramp convergence to target conditions within 5% band *)
        IF (ABS(rVotedPlenumPress_bar - rTargetStagPress_bar) < (rTargetStagPress_bar * 0.06)) AND
           (ABS(rEstBulkEnthalpy_MJpkg - rTargetEnthalpy_MJpkg) < (rTargetEnthalpy_MJpkg * 0.08)) THEN
            iState := 40; (* Steady-state Hypersonic Testing *)
        END_IF;

