            iState := 50; (* Commenced normal shutdown ramp *)
        END_IF;

    40: (* STATE 40: ACTIVE_HYPERSONIC_TEST_MPC_REGULATION *)
        wSystemStatusWord       := 16#0010; (* State 40 Bit - RUNNING *)
